function findDuplicates(arr) {
  const frequency = {};
  const duplicates = [];

  for (const num of arr) {
    frequency[num] = (frequency[num] || 0) + 1;
  }

  for (const num in frequency) {
    if (frequency[num] > 1) {
      duplicates.push(Number(num));
    }
  }

  return duplicates;
}

