function maxOccurrence(arr) {
  const frequency = {};
  let max = 0;
  let result = null;

  for (const num of arr) {
    frequency[num] = (frequency[num] || 0) + 1;

    if (frequency[num] > max) {
      max = frequency[num];
      result = num;
    }
  }

  return result;
}

