function flattenObject(obj, parent = "", result = {}) {
  for (const key in obj) {
    const newKey = parent ? `${parent}.${key}` : key;

    if (
      typeof obj[key] === "object" &&
      obj[key] !== null &&
      !Array.isArray(obj[key])
